// ============================================
// HMAC VERIFICATION - RFC-099
// ============================================

const crypto = require('crypto');

const input = $input.first().json;
const body = input.body || input;
const headers = input.headers || {};

// Get HMAC signature from header
const signatureHeader = headers['x-webhook-signature'] || headers['X-Webhook-Signature'] || '';
const providedSignature = signatureHeader.replace('sha256=', '');

// Get secret from env
const secret = process.env.N8N_RAG_WEBHOOK_SECRET;

if (!secret) {
  return {
    hmac_valid: false,
    error: 'N8N_RAG_WEBHOOK_SECRET not configured',
    http_code: 500
  };
}

if (!signatureHeader) {
  return {
    hmac_valid: false,
    error: 'Missing X-Webhook-Signature header',
    http_code: 401
  };
}

// Compute HMAC-SHA256
// Body should be the raw JSON string
const bodyString = JSON.stringify(body, null, 0); // Compact JSON
const hmac = crypto.createHmac('sha256', secret);
hmac.update(bodyString, 'utf8');
const computedSignature = hmac.digest('hex');

// Timing-safe comparison
const isValid = crypto.timingSafeEqual(
  Buffer.from(providedSignature, 'hex'),
  Buffer.from(computedSignature, 'hex')
);

if (!isValid) {
  return {
    hmac_valid: false,
    error: 'Invalid HMAC signature',
    http_code: 401,
    debug: {
      provided: providedSignature.substring(0, 16) + '...',
      computed: computedSignature.substring(0, 16) + '...'
    }
  };
}

return {
  hmac_valid: true,
  body: body,
  headers: headers
};

// ============================================
// VALIDATION PAYLOAD - RFC-099 §3.2
// ============================================

const body = $('Verify HMAC').item.json.body;
const errors = [];

// Required fields
const sourceId = body.source_id;
const tenantId = body.tenant_id;
const guildId = body.guild_id;
const botId = body.bot_id;
const active = body.active;
const fileType = body.file_type;

// File source (b2_file_key OR url)
const b2FileKey = body.b2_file_key || null;
const url = body.url || null;

// Optional fields
const extractionMethod = body.extraction_method || 'auto';
const title = body.title || null;
const lang = body.lang || null;
const callbackUrls = body.callback_urls || {};
const qdrantTarget = body.qdrant_target || {};

// Validate required
if (!sourceId) errors.push('source_id requis');
if (!tenantId) errors.push('tenant_id requis');
if (!guildId) errors.push('guild_id requis');
if (!botId) errors.push('bot_id requis');
if (active === undefined || active === null) errors.push('active requis');
if (!fileType) errors.push('file_type requis');

// File source validation
if (!b2FileKey && !url) {
  errors.push('b2_file_key ou url requis');
}

// Callback URLs validation
if (!callbackUrls.progress || !callbackUrls.complete || !callbackUrls.error) {
  errors.push('callback_urls.{progress,complete,error} requis');
}

if (errors.length > 0) {
  return {
    valid: false,
    errors: errors,
    source_id: sourceId
  };
}

// Extract Qdrant config (with fallback to env)
const qdrantConfig = {
  host: qdrantTarget.host || process.env.QDRANT_SHARED_1_HOST || 'host3.local',
  port: qdrantTarget.port || process.env.QDRANT_SHARED_1_PORT || 20001,
  api_key: qdrantTarget.api_key || process.env.QDRANT_SHARED_1_API_KEY || ''
};

return {
  valid: true,
  source_id: sourceId,
  tenant_id: tenantId,
  guild_id: guildId,
  bot_id: botId,
  active: active,
  file_type: fileType,
  b2_file_key: b2FileKey,
  url: url,
  extraction_method: extractionMethod,
  title: title,
  lang: lang,
  callback_urls: callbackUrls,
  qdrant: qdrantConfig,
  start_time: Date.now()
};

// ============================================
// CALLBACK PROGRESS - Helper function
// ============================================

const ctx = $('Validate Payload').item.json;

return {
  url: ctx.callback_urls.progress,
  body: {
    status: 'pending',
    progress_percent: 10,
    chunk_count: 0
  },
  context: ctx
};

// ============================================
// PLACEHOLDER: EXTRACTION
// TODO: Implement real extraction
// ============================================

const ctx = $('Prepare Callback Start').item.json.context;

// Placeholder extracted text
const extractedText = `[PLACEHOLDER EXTRACTION]\n\nSource: ${ctx.source_id}\nType: ${ctx.file_type}\nMethod: ${ctx.extraction_method}\n\nThis is placeholder text for testing the RAG pipeline.\nReal implementation will fetch and extract content from B2 or URL.\n\nLorem ipsum dolor sit amet, consectetur adipiscing elit. Sed do eiusmod tempor incididunt ut labore et dolore magna aliqua. Ut enim ad minim veniam, quis nostrud exercitation ullamco laboris.`;

return {
  ...ctx,
  extracted_text: extractedText,
  extraction_success: true,
  char_count: extractedText.length
};

// ============================================
// CHUNKING - RFC-099
// ============================================

const ctx = $('Extract Content (PLACEHOLDER)').item.json;
const text = ctx.extracted_text || '';

// Chunking parameters
const CHUNK_SIZE = 1000; // characters
const CHUNK_OVERLAP = 200; // overlap

const chunks = [];
let currentChunk = '';
let chunkIndex = 0;

// Split by paragraphs
const paragraphs = text.split(/\n\n+/);

for (const para of paragraphs) {
  if (currentChunk.length + para.length > CHUNK_SIZE && currentChunk.length > 0) {
    // Save chunk
    chunks.push({
      index: chunkIndex,
      text: currentChunk.trim(),
      char_count: currentChunk.trim().length
    });
    chunkIndex++;

    // Overlap
    const words = currentChunk.split(' ');
    const overlapWords = words.slice(-Math.ceil(CHUNK_OVERLAP / 5));
    currentChunk = overlapWords.join(' ') + '\n\n' + para;
  } else {
    currentChunk += (currentChunk ? '\n\n' : '') + para;
  }
}

// Last chunk
if (currentChunk.trim()) {
  chunks.push({
    index: chunkIndex,
    text: currentChunk.trim(),
    char_count: currentChunk.trim().length
  });
}

return {
  ...ctx,
  chunks: chunks,
  chunk_count: chunks.length
};

// ============================================
// PLACEHOLDER: EMBEDDING + QDRANT UPSERT
// TODO: Implement OpenAI embedding + Qdrant
// ============================================

const ctx = $('Chunk Text').item.json;

// In real implementation:
// 1. Batch embed chunks (text-embedding-3-small, 1536d)
// 2. Create collection tenant_{tenant_id}_default if not exists
// 3. Upsert points with 4 IDs in payload

// Simulate success
return {
  ...ctx,
  embedding_success: true,
  qdrant_success: true,
  qdrant_collection: `tenant_${ctx.tenant_id}_default`,
  points_upserted: ctx.chunk_count,
  duration_ms: Date.now() - ctx.start_time
};

// ============================================
// PREPARE CALLBACK COMPLETE
// ============================================

const ctx = $('Embed + Upsert Qdrant (PLACEHOLDER)').item.json;

return {
  url: ctx.callback_urls.complete,
  body: {
    success: true,
    chunk_count: ctx.chunk_count,
    duration_ms: ctx.duration_ms
  },
  tenant_id: ctx.tenant_id
};
